CREATE TYPE "vehicle_kind" AS ENUM ('car', 'truck', 'bike');
CREATE TABLE "vehicle" ( "id" serial NOT NULL, "kind" vehicle_kind NOT NULL, "name" varchar NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "uq-vehicle-id-kind" UNIQUE ("id", "kind") );
CREATE TABLE "car" ( "id" integer NOT NULL, "seats" smallint NOT NULL, "kind" vehicle_kind GENERATED ALWAYS AS ('car') STORED, PRIMARY KEY ("id"), CONSTRAINT "fk-car-id-kind" FOREIGN KEY ("id", "kind") REFERENCES "vehicle" ("id", "kind") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE );
CREATE TABLE "truck" ( "vehicle_id" integer NOT NULL, "axles" smallint NOT NULL, "payload_kg" integer NOT NULL, "kind" vehicle_kind GENERATED ALWAYS AS ('truck') STORED, PRIMARY KEY ("vehicle_id"), CONSTRAINT "fk-truck-vehicle_id-kind" FOREIGN KEY ("vehicle_id", "kind") REFERENCES "vehicle" ("id", "kind") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE );
ALTER TABLE "vehicle" ADD COLUMN "car_id" integer GENERATED ALWAYS AS ((CASE WHEN ("kind" = 'car') THEN "id" END)) STORED, ADD COLUMN "truck_id" integer GENERATED ALWAYS AS ((CASE WHEN ("kind" = 'truck') THEN "id" END)) STORED, ADD CONSTRAINT "fk-vehicle-car_id" FOREIGN KEY ("car_id") REFERENCES "car" ("id") DEFERRABLE INITIALLY IMMEDIATE, ADD CONSTRAINT "fk-vehicle-truck_id" FOREIGN KEY ("truck_id") REFERENCES "truck" ("vehicle_id") DEFERRABLE INITIALLY IMMEDIATE;
CREATE SCHEMA "market";
CREATE TYPE "market"."listing_category" AS ENUM ('apartment', 'building_plot');
CREATE TABLE "market"."listing" ( "tenant_id" integer NOT NULL, "id" bigint NOT NULL, "category" market.listing_category NOT NULL, "title" varchar NOT NULL, CONSTRAINT "pk-listing" PRIMARY KEY ("tenant_id", "id"), CONSTRAINT "uq-listing-tenant_id-id-category" UNIQUE ("tenant_id", "id", "category") );
CREATE TABLE "market"."flat" ( "tenant" integer NOT NULL, "listing" bigint NOT NULL, "rooms" smallint NOT NULL, "category" market.listing_category GENERATED ALWAYS AS ('apartment') STORED, CONSTRAINT "pk-flat" PRIMARY KEY ("tenant", "listing"), CONSTRAINT "fk-flat-tenant-listing-category" FOREIGN KEY ("tenant", "listing", "category") REFERENCES "market"."listing" ("tenant_id", "id", "category") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE );
ALTER TABLE "market"."listing" ADD COLUMN "apartment_tenant_id" integer GENERATED ALWAYS AS ((CASE WHEN ("category" = 'apartment') THEN "tenant_id" END)) STORED, ADD COLUMN "apartment_id" bigint GENERATED ALWAYS AS ((CASE WHEN ("category" = 'apartment') THEN "id" END)) STORED, ADD CONSTRAINT "fk-listing-apartment_tenant_id-apartment_id" FOREIGN KEY ("apartment_tenant_id", "apartment_id") REFERENCES "market"."flat" ("tenant", "listing") DEFERRABLE INITIALLY IMMEDIATE;
